"""CSV 读取与解析模块（REQ-001）。

支持 UTF-8 BOM 报销记录 CSV，校验必需列及字段格式：
- date: YYYY-MM-DD
- amount: 两位小数，保存为 Decimal
- currency: 仅允许 CNY

坏行记录 ParseError(line_no, reason)，不中断后续处理。
"""

from __future__ import annotations

import codecs
import csv
import os
import re
from collections.abc import Sequence
from decimal import Decimal, InvalidOperation
from pathlib import Path

DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
REQUIRED_COLUMNS = ("date", "employee", "category", "amount", "currency", "note")


class ParseError:
    """单行解析失败信息。"""

    __slots__ = ("line_no", "reason")

    def __init__(self, line_no: int, reason: str) -> None:
        self.line_no = line_no
        self.reason = reason

    def __repr__(self) -> str:
        return f"ParseError(line_no={self.line_no!r}, reason={self.reason!r})"


class CsvParseResult:
    """解析结果容器。"""

    __slots__ = ("records", "errors")

    def __init__(self, records: Sequence[dict], errors: Sequence[ParseError]) -> None:
        self.records = records
        self.errors = errors

    def __repr__(self) -> str:
        return (
            f"CsvParseResult(records={len(self.records)}, errors={len(self.errors)})"
        )


def _validate_date(value: str) -> bool:
    if not DATE_RE.match(value):
        return False
    parts = value.split("-")
    year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
    if not (1 <= month <= 12 and 1 <= day <= 31):
        return False
    return True


def _validate_amount(value: str) -> tuple[bool, Decimal | None]:
    if not re.match(r"^\d+\.\d{2}$", value):
        return False, None
    try:
        return True, Decimal(value)
    except InvalidOperation:
        return False, None


def _validate_currency(value: str) -> bool:
    return value == "CNY"


def parse_csv(text: str) -> CsvParseResult:
    """解析 CSV 文本，支持 UTF-8 BOM。

    参数:
        text: CSV 文本内容。

    返回:
        CsvParseResult，包含合法记录列表和解析错误列表。
    """
    if not text or not text.strip():
        return CsvParseResult([], [])

    if text.startswith("\ufeff"):
        text = text[1:]

    reader = csv.DictReader(text.strip().splitlines())
    fieldnames = reader.fieldnames

    if fieldnames is None:
        return CsvParseResult([], [])

    # strip BOM or whitespace from first field name
    cleaned_fields = [f.strip() for f in fieldnames]
    stripped_fieldnames = [f.lstrip("\ufeff") for f in fieldnames]

    required_set = set(REQUIRED_COLUMNS)
    present_set = set(stripped_fieldnames)
    if not required_set.issubset(present_set):
        missing = required_set - present_set
        err = ParseError(
            line_no=1,
            reason=f"缺少必需列: {', '.join(sorted(missing))}",
        )
        return CsvParseResult([], [err])

    records: list[dict] = []
    errors: list[ParseError] = []

    for row_idx, row in enumerate(reader, start=2):
        # Re-key with stripped field names so downstream logic sees clean keys
        cleaned_row = dict(zip(stripped_fieldnames, row.values()))

        row_errors: list[str] = []

        date_val = cleaned_row.get("date", "").strip()
        if not date_val:
            row_errors.append("date 字段为空")
        elif not _validate_date(date_val):
            row_errors.append(f"date 格式无效: {date_val!r}")

        amount_str = cleaned_row.get("amount", "").strip()
        if not amount_str:
            row_errors.append("amount 字段为空")
        else:
            amt_ok, amt_dec = _validate_amount(amount_str)
            if not amt_ok:
                row_errors.append(f"amount 格式无效: {amount_str!r}")
            else:
                cleaned_row["amount"] = amt_dec

        currency_val = cleaned_row.get("currency", "").strip()
        if not _validate_currency(currency_val):
            row_errors.append(f"currency 仅允许 CNY，当前值: {currency_val!r}")

        if row_errors:
            errors.append(ParseError(line_no=row_idx, reason="; ".join(row_errors)))
        else:
            records.append(cleaned_row)

    return CsvParseResult(records=records, errors=errors)


def parse_csv_file(path: object) -> CsvParseResult:
    """从 UTF-8 文件解析 CSV，自动处理 BOM。

    参数:
        path: 文件路径（str 或 pathlib.Path）。

    返回:
        CsvParseResult。
    """
    if not isinstance(path, (str, os.PathLike)):
