    try:
        with open(filepath, encoding="utf-8", newline="") as f:
            content = f.read()
    except FileNotFoundError:
        err = ParseError(line_no=0, reason=f"文件不存在: {filepath}")
        return CsvParseResult([], [err])
    except PermissionError:
        err = ParseError(line_no=0, reason=f"权限不足: {filepath}")
        return CsvParseResult([], [err])

    return parse_csv(content)

